package net.officefloor.hq.app.contact;

import jakarta.persistence.Entity;
import jakarta.persistence.FetchType;
import jakarta.persistence.GeneratedValue;
import jakarta.persistence.GenerationType;
import jakarta.persistence.Id;
import jakarta.persistence.JoinColumn;
import jakarta.persistence.ManyToOne;
import jakarta.persistence.Table;
import net.officefloor.hq.app.client.Client;

/** A person to contact at a client, with their role there. */
@Entity
@Table(name = "contact")
public class Contact {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @ManyToOne(fetch = FetchType.LAZY, optional = false)
    @JoinColumn(name = "client_id", nullable = false)
    private Client client;

    private String name;

    private String email;

    private String role;

    protected Contact() {
    }

    public Contact(Client client, String name, String email, String role) {
        this.client = client;
        this.name = name;
        this.email = email;
        this.role = role;
    }

    public Long getId() {
        return id;
    }

    public Client getClient() {
        return client;
    }

    public String getName() {
        return name;
    }

    public String getEmail() {
        return email;
    }

    public String getRole() {
        return role;
    }
}
package net.officefloor.hq.app.contact;

/** A contact; {@code primary} marks the client's main contact. */
public record ContactResponse(Long id, Long clientId, String name, String email, String role, boolean primary) {

    static ContactResponse from(Contact contact) {
        Contact primary = contact.getClient().getPrimaryContact();
        return new ContactResponse(contact.getId(), contact.getClient().getId(), contact.getName(),
                contact.getEmail(), contact.getRole(), primary != null && primary.getId().equals(contact.getId()));
    }
}
package net.officefloor.hq.app.contact;

import java.util.List;
import java.util.Optional;
import org.springframework.data.jpa.repository.JpaRepository;

public interface ContactRepository extends JpaRepository<Contact, Long> {

    /** A client's contacts in the order they were added. */
    List<Contact> findByClientIdOrderById(Long clientId);

    /** One of a client's contacts, if it is theirs. */
    Optional<Contact> findByIdAndClientId(Long id, Long clientId);

    /** How many contacts a client has. */
    long countByClientId(Long clientId);
}
package net.officefloor.hq.app.contact;

import jakarta.validation.Valid;
import java.util.List;
import org.springframework.http.HttpStatus;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.PostMapping;
